import React from 'react'
import { Container, Row, Col } from "react-bootstrap";
import Crab_Pasta from "../../assets/images/crab_pasta.jpg";
import Salad from "../../assets/images/salad.jpg";
import Cheese_Board from "../../assets/images/cheese_board.jpg";
import Pizza from "../../assets/images/pizza.png";
import "../../styles/Section5Style.css";

const Section5 = () => {
  return (
    <section className="menu_reviews">
        <Container>
            <Row>
                <Col lg={6}md={6} sm={12}>
                    <h2>Our menu offers convenience, good prices, variety, and speed.</h2>
                    <p>We take great care to ensure that your meal, regardless of the time, is always made with the freshest and most flavorful ingredients. We offer more than 30 options, including pasta, salads, risottos, proteins, and other hot dishes.</p>
                </Col>
                <Col lg={6} className="d-flex align-items-center">
                    <div className="review_dishes">
                        <img src={Crab_Pasta} alt="Crab Pasta" className=""/>
                        <img src={Salad} alt="Salad" className=""/>
                        <img src={Cheese_Board} alt="Cheese Board" className=""/>
                        <img src={Pizza} alt="Pizza" className=""/>
                    </div>
                </Col>
            </Row>
        </Container>

    </section>
  )
}

export default Section5
